"""sport template v9 (n112): F5 Board = the NFL Picks Board — the KPI strip (plays on the slate · leans · passed · season record ·
biggest edge), type chips, best-per-player / every-line, the play cards (green = plays, amber = leans) with model vs market, the
edge bar and the cohort chips (how this type of position at this edge size has actually graded; the market's own record), then
the game model vs the market table and the full ledger. Rerunnable (guarded)."""
import os, sys
P = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'sport_template.html')
s = open(P, encoding='utf-8').read()
if 'function picksBoard()' in s:
    print('already applied'); sys.exit()
def rep(old, new):
    global s
    assert s.count(old) == 1, (s.count(old), old[:90])
    s = s.replace(old, new)
rep("function ledger(){const el=$('#picks');", "function ledgerTable(el){")
rep("""</tbody></table></div>`}
/* ---- v4: signal engine + the mirrored tabs ---- */""", r"""</tbody></table></div>`}
function ledger(){picksBoard()}
const EDGE_PLAY=.06,EDGE_LEAN=.03;
const edgeVal=p=>p.type==='PROP'?+p.edge:p.type==='ML'?+p.edge:Math.abs(+p.edge)/14;   /* one scale: props and ML in probability, spreads & totals |points|/14 */
const bucket=e=>e>=.18?'18%+':e>=.10?'10–18%':e>=.06?'6–10%':e>=.03?'3–6%':'<3%';
function cohort(type,e){const B=bucket(e);const R=J.picks.filter(p=>p.type===type&&(p.result==='W'||p.result==='L'||p.result==='P')&&bucket(edgeVal(p))===B);const w=R.filter(p=>p.result==='W').length,l=R.filter(p=>p.result==='L').length,pu=R.filter(p=>p.result==='P').length;const M=J.picks.filter(p=>p.type===type&&(p.result==='W'||p.result==='L'));const mw=M.filter(p=>p.result==='L').length;   /* the market's record = the other side */
  return {b:B,w,l,pu,hit:w+l?w/(w+l):null,mw,ml:M.length-mw,mhit:M.length?mw/M.length:null}}
function picksBoard(){const el=$('#picks');const gs=GAMESD();const GK=new Set(gs.map(g=>g.away+'@'+g.home));const days=new Set(gs.map(g=>g.day));const ty=G.pt||'';const best=G.pbest!==false;
  const P=J.picks.filter(p=>GK.has(p.game)&&days.has(p.date)).filter(p=>inT(p.game.split('@')[0])||inT(p.game.split('@')[1]));
  /* plays = frozen positions on the slate; leans = priced props the model likes 3–6% but did not freeze, and game edges under the bar */
  const frozenRef=new Set(P.map(p=>p.ref));const leansP=PR.filter(r=>okProp(r)&&r.edge>=EDGE_LEAN&&r.edge<.05&&GK.has(r.team+'@'+r.opp)||okProp(r)&&r.edge>=EDGE_LEAN&&r.edge<.05&&GK.has(r.opp+'@'+r.team)).map(r=>({type:'PROP',game:gs.find(g=>g.away===r.team||g.home===r.team)?.away+'@'+gs.find(g=>g.away===r.team||g.home===r.team)?.home,side:r.side,line:r.line,model:r.proj,market_ref:r.p_imp,edge:r.edge,player:r.player,pid:r.pid,market:r.market,price:r.price,book:r.book,lean:true,date:r.date}));
  const leansG=gs.flatMap(g=>{const o=[];const se=g.home_line!=null&&g.model_margin!=null?g.model_margin+g.home_line:null;const te=g.ou&&g.model_total!=null?g.model_total-parseFloat(g.ou):null;const k=g.away+'@'+g.home;
    if(se!=null&&Math.abs(se)>=1&&Math.abs(se)<2.5&&!P.some(p=>p.type==='ATS'&&p.game===k))o.push({type:'ATS',game:k,side:se>0?g.home:g.away,line:se>0?g.home_line:-g.home_line,model:g.model_margin,market_ref:g.home_line,edge:Math.abs(se),lean:true,date:g.day});
    if(te!=null&&Math.abs(te)>=1.5&&Math.abs(te)<3&&!P.some(p=>p.type==='TOTAL'&&p.game===k))o.push({type:'TOTAL',game:k,side:te>0?'OVER':'UNDER',line:parseFloat(g.ou),model:g.model_total,market_ref:parseFloat(g.ou),edge:Math.abs(te),lean:true,date:g.day});return o});
  let plays=P.slice(),leans=leansP.concat(leansG);if(ty){plays=plays.filter(p=>p.type===ty);leans=leans.filter(p=>p.type===ty)}
  if(best){const seen=new Set();plays=plays.sort((a,b)=>edgeVal(b)-edgeVal(a)).filter(p=>{const k=p.type==='PROP'?p.pid+'|'+p.market:p.type+'|'+p.game;if(seen.has(k))return false;seen.add(k);return true})}
  plays.sort((a,b)=>edgeVal(b)-edgeVal(a));leans.sort((a,b)=>edgeVal(b)-edgeVal(a));
  const passed=PR.filter(r=>r.n_books>=2&&r.edge<EDGE_LEAN&&(GK.has(r.team+'@'+r.opp)||GK.has(r.opp+'@'+r.team))).length;
  const S=J.picks.filter(p=>p.result==='W'||p.result==='L'||p.result==='P');const sw=S.filter(p=>p.result==='W').length,sl=S.filter(p=>p.result==='L').length,sp=S.filter(p=>p.result==='P').length;const su=S.reduce((a,p)=>a+(p.result==='W'?(p.type==='ML'&&p.market_ref>0&&p.market_ref<1?1/p.market_ref-1:0.909):p.result==='L'?-1:0),0);
  const big=plays[0];const LBL={ML:'moneyline',ATS:'spread',TOTAL:'total',PROP:'player prop'};
  const card=(p,lean)=>{const g=gs.find(x=>x.away+'@'+x.home===p.game)||{};const e=edgeVal(p);const c=cohort(p.type,e);const [a,h]=p.game.split('@');const pts=p.type==='ATS'||p.type==='TOTAL';
    const head=p.type==='PROP'?`<div class="pk-who">${pname(p)} <span class="mini">${PL[p.pid]?(PL[p.pid].team===h?'vs '+a:'@ '+h):''}</span></div><div class="pk-pick"><b style="color:${p.side==='Over'?'var(--green)':'var(--red)'}">${esc(String(p.side))}</b> <span class="mini">${MKL[p.market]||p.market} ${p.line}</span></div>`:`<div class="pk-who">${tc(a)} <span class="dim">@</span> ${tc(h)}</div><div class="pk-pick"><b>${esc(String(p.side))}${p.type==='ATS'?' '+(p.line>0?'+':'')+p.line:p.type==='TOTAL'?' '+p.line:''}</b> <span class="mini">${LBL[p.type]}</span></div>`;
    const modelTxt=p.type==='PROP'?`model <b>${p.model}</b> vs market <b>${p.line}</b> <span class="mini">(${(100*(p.market_ref||0)).toFixed(0)}% over)</span>`:p.type==='ML'?`model <b>${(100*p.model).toFixed(0)}%</b> vs market <b>${(100*p.market_ref).toFixed(0)}%</b>`:p.type==='ATS'?`model <b>${h} ${p.model>0?'-':'+'}${Math.abs(+p.model).toFixed(1)}</b> vs market <b>${h} ${p.market_ref>0?'+':''}${p.market_ref}</b>`:`model <b>${p.model}</b> vs market <b>${p.market_ref}</b>`;
    const edgeTxt=p.type==='PROP'||p.type==='ML'?`${(100*e).toFixed(1)}% ${p.type==='PROP'?'edge':''}`:`${Math.abs(+p.edge).toFixed(1)} pts`;
    return `<div class="pk ${lean?'lean':'play'}"><div class="pk-top"><span class="pk-ty">${LBL[p.type]||p.type}</span><span class="mini">${g.date?dayKey(g.date)+' '+fmtT(g.date):p.date}</span></div>${head}<div class="pk-mm">${modelTxt}<span class="pk-edge"><i style="width:${Math.min(60,Math.round(300*e))}px"></i>${edgeTxt}</span></div>
      <div class="pk-ch"><span class="ch ${c.hit==null?'':c.hit>=.524?'g':'r'}" title="how ${LBL[p.type]} positions with an edge in this band have graded">edge ${c.b} · ${c.w}-${c.l}${c.pu?'-'+c.pu:''} · ${c.hit==null?'—':(100*c.hit).toFixed(0)+'%'}</span><span class="ch ${c.mhit==null?'':c.mhit>=.524?'g':'r'}" title="the market's own record against the model on this type">market ${c.mw}-${c.ml} · ${c.mhit==null?'—':(100*c.mhit).toFixed(0)+'%'}</span>${p.book?`<span class="ch bk">${esc(String(p.book)).slice(0,10)}${p.price!=null&&p.price!==''?' '+amer(p.price):''}</span>`:''}${p.result?`<span class="res ${p.result}">${p.result}</span>`:''}</div></div>`};
  const k=(t,v,s_,cls='')=>`<div class="kpi ${cls}"><div class="k">${t}</div><div class="v">${v}</div><div class="s">${s_}</div></div>`;
  el.innerHTML=`<div class="kpis strip">${k('plays on this slate',`<span class="rise">${plays.length}</span>`,`frozen · ${plays.filter(p=>p.type==='PROP').length} props · ${plays.filter(p=>p.type!=='PROP').length} game plays`)}${k('leans',`<span style="color:#e8b100">${leans.length}</span>`,'edge 3–6% (props) or under the freeze bar (games) · data, not a position')}${k('priced, passed',passed,'props the model does not like · under 3%')}${k('plays · season record',`${sw}-${sl}${sp?'-'+sp:''}`,`${su>=0?'+':''}${su.toFixed(2)} u · ${S.length?(100*sw/Math.max(1,sw+sl)).toFixed(1):'·'}% hit · ${S.length} graded`,sw>sl?'g':sl>sw?'r':'')}${big?k('biggest edge',`${edgeVal(big)>=.06?'<span class="rise">':''}${big.type==='ATS'||big.type==='TOTAL'?Math.abs(+big.edge).toFixed(1)+' pts':(100*edgeVal(big)).toFixed(1)+'%'}${edgeVal(big)>=.06?'</span>':''}`,`${big.type==='PROP'?esc(big.player)+' '+big.side+' '+(MKL[big.market]||big.market)+' '+big.line:big.game+' · '+big.side+' '+(big.line??'')}`):''}</div>
   <div class="controls"><span class="chips" id="pkTy"><button data-t="" class="${ty?'':'on'}">all</button>${['ML','ATS','TOTAL','PROP'].map(t=>`<button data-t="${t}" class="${ty===t?'on':''}">${LBL[t]} <span class="dim">${P.filter(p=>p.type===t).length}</span></button>`).join('')}</span><span class="chips" id="pkBest"><button data-b="1" class="${best?'on':''}">best per player</button><button data-b="0" class="${best?'':'on'}">every line</button></span><span class="note">green cards = plays: the frozen positions on this slate (props at 5+ points with two books; games past the freeze bar) · amber = leans (the model is on a side, not strongly) · cohort = how positions of this type with an edge this size have actually graded, green clears 52.4% · market = the market's own record against the model on the type · best per player keeps the strongest line per player and market</span></div>
   <div class="panel"><h3>the model likes <span class="f">${plays.length} plays · sorted by edge</span></h3><div class="pks">${plays.map(p=>card(p,false)).join('')||'<p class="note">nothing frozen on this slate yet — positions freeze when lines post and the model clears its bar</p>'}</div></div>
   <div class="panel"><h3>leans <span class="f">${leans.length} · the model is on a side, not strongly</span></h3><div class="pks">${leans.map(p=>card(p,true)).join('')||'<p class="note">none</p>'}</div></div>
   <div id="pkLines"></div><div id="pkLedger"></div>`;
  const L=$('#pkLines');
  /* the game model vs the market, then the ledger */
  const pickCell=g=>{const k=g.away+'@'+g.home;const ps=J.picks.filter(p=>p.game===k&&p.date===g.day&&p.type!=='PROP');return ps.length?ps.map(p=>`<span class="mini"><b>${p.type}</b> ${esc(String(p.side))} ${p.line??''}${p.result?` <span class="res ${p.result}">${p.result}</span>`:''}</span>`).join(' '):'<span class="dim">pass</span>'};
  L.innerHTML=`<div class="panel wrap-x"><h3>game model vs the market <span class="f">every game on the slate · spread and total from DraftKings via ESPN · gap = model − market · call = the frozen position, or pass</span></h3><table><thead><tr><th>tip (CT)</th><th>game</th><th>spread</th><th>model</th><th>gap</th><th>total</th><th>model</th><th>gap</th><th>home win</th><th>market</th><th>call</th></tr></thead><tbody>${gs.map(g=>{const se=g.home_line!=null&&g.model_margin!=null?g.model_margin+g.home_line:null;const te=g.ou&&g.model_total!=null?g.model_total-parseFloat(g.ou):null;const me=g.imp_home!=null&&g.p_home!=null?g.p_home-g.imp_home:null;return `<tr><td class="mono mini">${dayKey(g.date).replace(/,.*$/,'')} ${fmtT(g.date)}</td><td>${tc(g.away)} <span class="dim">@</span> ${tc(g.home)}</td><td class="mono">${g.home_line!=null?`${g.home} ${g.home_line>0?'+':''}${g.home_line}`:'—'}</td><td class="mono">${g.model_margin!=null?`${g.home} ${g.model_margin>0?'-':'+'}${Math.abs(g.model_margin).toFixed(1)}`:'—'}</td><td class="mono" style="color:${se==null?'var(--dim)':Math.abs(se)>=2.5?'var(--green)':'var(--txt)'}">${se==null?'':(se>0?'+':'')+se.toFixed(1)}</td><td class="mono">${g.ou||'—'}</td><td class="mono">${g.model_total??'—'}</td><td class="mono" style="color:${te==null?'var(--dim)':Math.abs(te)>=3?'var(--green)':'var(--txt)'}">${te==null?'':(te>0?'+':'')+te.toFixed(1)}</td><td class="mono"><b>${g.p_home!=null?(100*g.p_home).toFixed(0)+'%':'—'}</b></td><td class="mono" style="color:${me==null?'var(--dim)':me>=.06?'var(--green)':'var(--txt)'}">${g.imp_home!=null?(100*g.imp_home).toFixed(0)+'%':'—'}</td><td>${pickCell(g)}</td></tr>`}).join('')}</tbody></table></div>`;
  ledgerTable($('#pkLedger'));
  el.querySelectorAll('#pkTy button').forEach(b=>b.onclick=()=>{G.pt=b.dataset.t;picksBoard()});el.querySelectorAll('#pkBest button').forEach(b=>b.onclick=()=>{G.pbest=b.dataset.b==='1';picksBoard()});bindPL(el)}
/* ---- v4: signal engine + the mirrored tabs ---- */""")
rep(".mopen:hover{color:var(--txt);border-color:var(--acc)}",
    ".mopen:hover{color:var(--txt);border-color:var(--acc)}.pks{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:8px}.pk{border:1px solid var(--edge2);border-left:3px solid var(--green);border-radius:8px;padding:8px 10px;background:var(--s2);font-size:12px}.pk.lean{border-left-color:#e8b100}.pk-top{display:flex;justify-content:space-between;font-family:var(--mono);font-size:10px;color:var(--dim)}.pk-ty{color:var(--acc);letter-spacing:.1em;text-transform:uppercase;font-weight:700}.pk-who{margin:4px 0 2px;font-size:13px}.pk-pick{font-size:14px}.pk-mm{display:flex;justify-content:space-between;align-items:center;gap:8px;font-family:var(--mono);font-size:11px;color:var(--dim);margin:4px 0}.pk-mm b{color:var(--txt)}.pk-edge{display:inline-flex;align-items:center;gap:5px;color:var(--green);white-space:nowrap}.pk.lean .pk-edge{color:#e8b100}.pk-edge i{display:inline-block;height:6px;border-radius:3px;background:currentColor}.pk-ch{display:flex;flex-wrap:wrap;gap:4px;margin-top:4px}.pk-ch .ch{font:10px var(--mono);border:1px solid var(--edge2);border-radius:4px;padding:1px 6px;color:var(--dim)}.pk-ch .ch.g{color:var(--green);border-color:#15351f}.pk-ch .ch.r{color:var(--red);border-color:#3a1512}.pk-ch .ch.bk{color:var(--txt)}")
rep(" ledger:{what:'Every frozen position — moneyline, spread, total and player prop — graded against the line it was frozen with.',how:['frozen before tip-off, graded after','break-even at −110 is 52.4%']},",
    " ledger:{what:'The board: every play the model froze on this slate as a card — the pick, model vs market, the edge, and how positions like it have actually graded — then the leans, the game model against the market, and the full ledger.',how:['green cards = plays (frozen) · amber = leans (3–6%, data not a position) · passed = priced lines the model does not like','cohort = the graded record of this type of position at this edge size; market = the market\\'s own record against the model','break-even at −110 is 52.4% · best per player keeps the strongest line per player and market']},")
open(P, 'w', encoding='utf-8').write(s)
print('applied')
